# situ capability map v1
# schema: address.situ
# core:   offset size align repr atomic
#
# Core axes are always shown. Any other axis appears only where it has
# been weakened below its strongest value.
#
# Offsets are byte values, or byte:bit where a field does not start on
# a byte boundary. Sizes are bytes unless suffixed with `bit`.
#
# A struct's size is a bare number where it is fixed, `min..max` where
# it is bounded, and `min..` where nothing bounds it.

struct message size=6..50 mutate=Shifting address=Unstable repr=ValueConverted atomic=NonAtomic
  message.family                         offset=AbsoluteStatic(0x00) size=Fixed(1) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord
  message.type                           offset=AbsoluteStatic(0x01) size=Fixed(1) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord
  message.address_len                    offset=AbsoluteStatic(0x02) size=Fixed(1) align=Aligned(2) repr=MemoryIdentical atomic=AtomicWord
  message.address                        offset=AbsoluteStatic(0x03) size=Bounded(1, 45) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting
  message.port                           offset=Dynamic size=Fixed(2) align=Unaligned repr=ValueConverted atomic=NonAtomic address=Unstable
